/**
 * Synthetic inventory data with PLANTED patterns (no real data). The truth is generated by a plain simulation of daily movements, so every
 * snapshot is exactly "opening + movements" except where a defect is planted on purpose.
 *
 *  P01 fast mover, healthy cover            P07 stock below its minimum (cover is fine)
 *  P02 steady                               P08 12-15 snapshot is 7 lower than the movements say (unrecorded loss) → does not reconcile
 *  P03 slow mover: ~1 unit / 10 days, 1000 on hand (W2)   P09 negative stock (W2) – movements really drive it below zero
 *  P04 NON-moving: received once on 06-05, never issued   P10 transfers W1→W2 (two legs) and W2→W1 (one line) – NOT demand, NOT receipts
 *  P05 high value (120 EUR); 12-15 stated value is 20 % above qty × cost            P11 customer return, supplier return, write-off
 *  P06 stockout risk: 80 on hand, ~10.7 / day demand      P12 sugar: W1 in kg, W2 in g (same physical unit family)
 */
export type ILocale = 'lt' | 'pl';
export type IMoveType = 'receipt' | 'issue' | 'transfer_out' | 'transfer_in' | 'transfer_single' | 'return_in' | 'return_out' | 'adjustment';

export interface IMove {
  date: string;
  doc: string;
  type: IMoveType;
  sku: string;
  product: string;
  wh: string;
  /** transfer_single only: the receiving warehouse */
  whTo?: string;
  /** magnitude (always positive); the direction comes from the type */
  qty: number;
  unit: string;
  cost: number;
}
export interface ISnap {
  date: string;
  wh: string;
  sku: string;
  product: string;
  category: string;
  qty: number;
  unit: string;
  cost?: number;
  value?: number;
  min?: number;
}

export const START = '2025-06-01';
export const END = '2025-12-15';
export const SNAP_DATES = ['2025-08-31', '2025-09-30', '2025-10-31', '2025-11-30', '2025-12-15'];
/** default dashboard windows (rolling 30 days ending at the last date) */
export const CUR = { from: '2025-11-16', to: '2025-12-15' };
export const PREV = { from: '2025-10-17', to: '2025-11-15' };

const NAMES = {
  lt: ['Pienas 1 l', 'Miltai 1 kg', 'Skardinės', 'Senos prekės', 'Planšetė', 'Sviestas 200 g', 'Sūris', 'Kava 250 g', 'Sultys 1 l', 'Vanduo 0,5 l', 'Aliejus 1 l', 'Cukrus'],
  pl: ['Mleko 1 l', 'Mąka 1 kg', 'Puszki', 'Stare towary', 'Tablet', 'Masło 200 g', 'Ser', 'Kawa 250 g', 'Soki 1 l', 'Woda 0,5 l', 'Olej 1 l', 'Cukier'],
};
const CATS = {
  lt: { dairy: 'Pieno produktai', grocery: 'Bakalėja', other: 'Kita', elec: 'Elektronika', drinks: 'Gėrimai' },
  pl: { dairy: 'Nabiał', grocery: 'Spożywcze', other: 'Inne', elec: 'Elektronika', drinks: 'Napoje' },
};
export const WH = { lt: ['Vilnius', 'Kaunas'], pl: ['Łódź', 'Katowice'] };

const iso = (ms: number) => new Date(ms).toISOString().slice(0, 10);
const days = (() => { const a: string[] = []; for (let t = Date.parse(START + 'T00:00:00Z'); t <= Date.parse(END + 'T00:00:00Z'); t += 86400000) a.push(iso(t)); return a; })();
const isWeekday = (d: string) => { const w = new Date(d + 'T00:00:00Z').getUTCDay(); return w !== 0 && w !== 6; };

interface Plan {
  sku: string; idx: number; unit: string; cost: number; cat: keyof (typeof CATS)['lt']; wh: 0 | 1;
  /** stock on hand at END (from the movements) */
  target: number;
  issue: (d: string, i: number) => number;
  receipts?: (d: string, i: number) => number;
  min?: number;
}

export function makeInventory(locale: ILocale): { moves: IMove[]; snaps: ISnap[]; plans: Plan[] } {
  const N = NAMES[locale];
  const W = WH[locale];
  const wk = (n: number) => (d: string) => (isWeekday(d) ? n : 0);
  const every = (k: number, q: number, from = 0) => (_d: string, i: number) => (i >= from && i % k === 0 ? q : 0);
  const plans: Plan[] = [
    { sku: 'P01', idx: 0, unit: 'pcs', cost: 0.8, cat: 'dairy', wh: 0, target: 600, issue: (d, i) => (isWeekday(d) ? 20 + (i % 5) : 0), receipts: (d) => (new Date(d + 'T00:00:00Z').getUTCDay() === 1 ? 100 : 0), min: 100 },
    { sku: 'P02', idx: 1, unit: 'pcs', cost: 0.9, cat: 'grocery', wh: 0, target: 400, issue: wk(10), receipts: every(14, 60, 14) },
    { sku: 'P03', idx: 2, unit: 'pcs', cost: 2.5, cat: 'grocery', wh: 1, target: 1000, issue: every(10, 1, 10) },
    { sku: 'P04', idx: 3, unit: 'pcs', cost: 8, cat: 'other', wh: 0, target: 500, issue: () => 0 },
    { sku: 'P05', idx: 4, unit: 'pcs', cost: 120, cat: 'elec', wh: 0, target: 15, issue: (d, i) => (isWeekday(d) && i % 3 === 0 ? 1 : 0), receipts: every(30, 5, 5) },
    { sku: 'P06', idx: 5, unit: 'pcs', cost: 1.5, cat: 'dairy', wh: 0, target: 80, issue: wk(15), min: 50 },
    { sku: 'P07', idx: 6, unit: 'pcs', cost: 6, cat: 'dairy', wh: 0, target: 40, issue: wk(2), min: 60 },
    { sku: 'P08', idx: 7, unit: 'pcs', cost: 4, cat: 'grocery', wh: 0, target: 100, issue: wk(3) },
    { sku: 'P09', idx: 8, unit: 'pcs', cost: 1.1, cat: 'drinks', wh: 1, target: -4, issue: wk(6) },
    { sku: 'P10', idx: 9, unit: 'pcs', cost: 0.3, cat: 'drinks', wh: 0, target: 300, issue: wk(5) },
    { sku: 'P11', idx: 10, unit: 'pcs', cost: 2.2, cat: 'grocery', wh: 0, target: 250, issue: wk(4) },
    { sku: 'P12', idx: 11, unit: 'kg', cost: 1.1, cat: 'grocery', wh: 0, target: 800, issue: wk(8) },
  ];
  const moves: IMove[] = [];
  let doc = 7000;
  const add = (m: Omit<IMove, 'doc'> & { doc?: string }) => moves.push({ doc: m.doc ?? `${locale === 'lt' ? 'JD' : 'RK'}-${++doc}`, ...m });
  const bal = new Map<string, number>(); // key sku|wh → balance from the simulation (without the opening receipt)

  for (const p of plans) {
    const product = N[p.idx]!;
    const w = W[p.wh]!;
    let net = 0; // Σ(receipts − issues) excluding the opening receipt
    days.forEach((d, i) => {
      const q = p.issue(d, i);
      if (q > 0) { add({ date: d, type: 'issue', sku: p.sku, product, wh: w, qty: q, unit: p.unit, cost: p.cost }); net -= q; }
      const r = p.receipts?.(d, i) ?? 0;
      if (r > 0) { add({ date: d, type: 'receipt', sku: p.sku, product, wh: w, qty: r, unit: p.unit, cost: p.cost }); net += r; }
    });
    bal.set(`${p.sku}|${w}`, net);
  }
  // P10 also sells from W2 (2 / weekday)
  const p10 = plans[9]!;
  { let net = 0; days.forEach((d) => { if (isWeekday(d)) { add({ date: d, type: 'issue', sku: 'P10', product: N[9]!, wh: W[1]!, qty: 2, unit: 'pcs', cost: p10.cost }); net -= 2; } }); bal.set(`P10|${W[1]}`, net); }
  // P03 also needs a little W1 stock? no. P12 W2 (grams) has NO movements – only snapshots.

  // special flows
  const sp = (sku: string, idx: number) => ({ sku, product: N[idx]! });
  const tr = (d: string, docNo: string, from: string, to: string, q: number) => {
    add({ date: d, doc: docNo, type: 'transfer_out', ...sp('P10', 9), wh: from, qty: q, unit: 'pcs', cost: 0.3 });
    add({ date: d, doc: docNo, type: 'transfer_in', ...sp('P10', 9), wh: to, qty: q, unit: 'pcs', cost: 0.3 });
  };
  tr('2025-11-20', 'TR-1001', W[0]!, W[1]!, 100); // W1 → W2, two legs
  add({ date: '2025-12-05', doc: 'TR-1002', type: 'transfer_single', ...sp('P10', 9), wh: W[1]!, whTo: W[0]!, qty: 50, unit: 'pcs', cost: 0.3 }); // W2 → W1, ONE line
  add({ date: '2025-12-03', doc: 'RT-1', type: 'return_in', ...sp('P11', 10), wh: W[0]!, qty: 30, unit: 'pcs', cost: 2.2 });
  add({ date: '2025-11-10', doc: 'RT-2', type: 'return_out', ...sp('P11', 10), wh: W[0]!, qty: 20, unit: 'pcs', cost: 2.2 });
  add({ date: '2025-12-08', doc: 'ADJ-1', type: 'adjustment', ...sp('P11', 10), wh: W[0]!, qty: 15, unit: 'pcs', cost: 2.2 }); // write-off (stock goes DOWN)

  const net = (sku: string, w: string, upTo?: string) => {
    let n = 0;
    for (const m of moves) {
      if (m.sku !== sku || (upTo && m.date > upTo)) continue;
      const sign = m.type === 'receipt' || m.type === 'return_in' || m.type === 'transfer_in' ? 1 : -1;
      if (m.type === 'transfer_single') { if (m.wh === w) n -= m.qty; if (m.whTo === w) n += m.qty; continue; }
      if (m.wh === w) n += sign * m.qty;
    }
    return n;
  };
  // opening receipts: chosen so that the balance at END equals the target
  const targets: [string, number, number][] = [
    ...plans.map((p) => [p.sku, p.wh, p.target] as [string, number, number]),
    ['P10', 1, 200], ['P12', 1, 0],
  ];
  for (const [sku, wi, target] of targets) {
    if (sku === 'P12' && wi === 1) continue;
    const w = W[wi]!;
    const have = net(sku, w);
    const open = target - have;
    const pl = plans.find((x) => x.sku === sku)!;
    if (open > 0) moves.unshift({ date: sku === 'P04' ? '2025-06-05' : START, doc: `${locale === 'lt' ? 'JD' : 'RK'}-${sku}-OPEN`, type: 'receipt', sku, product: N[pl.idx]!, wh: w, qty: open, unit: pl.unit, cost: pl.cost });
    else if (open < 0) throw new Error(`fixture: ${sku} needs a negative opening receipt (${open})`);
  }
  moves.sort((a, b) => a.date.localeCompare(b.date) || a.doc.localeCompare(b.doc) || a.type.localeCompare(b.type));

  // snapshots: EXACT balances at every snapshot date
  const snaps: ISnap[] = [];
  const C = CATS[locale];
  const skus = new Map<string, Plan>(plans.map((p) => [p.sku, p]));
  const lines: [string, string][] = [...new Set(moves.map((m) => `${m.sku}|${m.wh}`).concat(moves.filter((m) => m.whTo).map((m) => `${m.sku}|${m.whTo}`)))].map((k) => k.split('|') as [string, string]);
  lines.push(['P12', W[1]!]);
  for (const date of SNAP_DATES) {
    for (const [sku, w] of lines) {
      const p = skus.get(sku)!;
      let qty = net(sku, w, date);
      if (sku === 'P12' && w === W[1]) qty = 300000; // grams (= 300 kg)
      if (qty === 0 && date !== END) continue;
      const g = sku === 'P12' && w === W[1];
      const cost = g ? 0.0011 : p.cost;
      const snap: ISnap = { date, wh: w, sku, product: N[p.idx]!, category: C[p.cat], qty, unit: g ? 'g' : p.unit, cost, value: Math.round(qty * cost * 100) / 100, min: p.min !== undefined && w === W[p.wh] ? p.min : undefined };
      if (date === END) {
        if (sku === 'P08') snap.qty = qty - 7, snap.value = Math.round((qty - 7) * cost * 100) / 100; // planted: unrecorded loss
        if (sku === 'P05') snap.value = Math.round(qty * cost * 1.2 * 100) / 100; // planted: stated value 20 % above qty × cost
        if (sku === 'P10' && w === W[1]) { snap.cost = undefined; snap.value = undefined; } // planted: missing cost (1 line)
      }
      if (qty === 0 && date === END && !(sku === 'P12')) continue;
      snaps.push(snap);
    }
  }
  return { moves, snaps, plans };
}

// ───────────── independent reference calculations (plain loops, no engine code) ─────────────
export const rnd = (n: number) => Math.round(n * 100) / 100;
export const snapsAt = (snaps: ISnap[], date: string) => snaps.filter((s) => s.date === date);
/** stock value of the snapshots of one date (lines with value only) */
export const valueAt = (snaps: ISnap[], date: string) => rnd(snapsAt(snaps, date).reduce((s, x) => s + (x.value ?? 0), 0));
export const signed = (m: IMove) => (m.type === 'receipt' || m.type === 'return_in' || m.type === 'transfer_in' ? 1 : -1) * m.qty;
